(5995195, 877161, 117372, '<td valign="top">love, love, love</td>', 'love, love, love', '2010-05-07 02:30:27.000000', NULL, 1),
(5995203, 876065, 41337, '<td valign="top">Cute. There''s an immediate connection to the challenge theme but doesn''t really go much further than that. Good job though.</td>', 'Cute. There''s an immediate connection to the challenge theme but doesn''t really go much further than that. Good job though.', '2010-05-07 02:45:33.000000', NULL, 1),
(5995206, 876728, 41337, '<td valign="top">As a movie poster it doesn''t really wow you but the photo is good and you didn''t go overboard with the design so good job there. The border probably wasn''t a good move since it takes away from the poster aspect.</td>', 'As a movie poster it doesn''t really wow you but the photo is good and you didn''t go overboard with the design so good job there. The border probably wasn''t a good move since it takes away from the poster aspect.', '2010-05-07 02:50:22.000000', NULL, 1),
(5995208, 876615, 41337, '<td valign="top">Only a psycho could have created this. :P</td>', 'Only a psycho could have created this. :P', '2010-05-07 02:52:39.000000', NULL, 1),
(5995211, 876963, 41337, '<td valign="top">Ha! Nice concept. I wonder though, if a subtle wave or ripple would have given it a little more coolness but I like what you did here. Now you seem to have gone out of your way to make it very unposter-like with the landscape and the border but for me they really don''t bother me. What does (a little) is the black outline on the font. Actually it doesn''t bother me. It''s just dated and not in that hip-retro way either. Ok I said enough. Good luck.</td>', 'Ha! Nice concept. I wonder though, if a subtle wave or ripple would have given it a little more coolness but I like what you did here. Now you seem to have gone out of your way to make it very unposter-like with the landscape and the border but for me they really don''t bother me. What does (a little) is the black outline on the font. Actually it doesn''t bother me. It''s just dated and not in that hip-retro way either. Ok I said enough. Good luck.', '2010-05-07 03:03:46.000000', NULL, 1),
(5995216, 876775, 110108, '<td valign="top">Though I find the poster acceptable :) I wd give 8</td>', 'Though I find the poster acceptable :) I wd give 8', '2010-05-07 03:19:30.000000', NULL, 1),
(5995245, 876193, 28742, '<td valign="top">not the only one to come up with a similar idea, but probably the best execution of it. Well done!</td>', 'not the only one to come up with a similar idea, but probably the best execution of it. Well done!', '2010-05-07 04:49:47.000000', NULL, 1),
(5995248, 876801, 28742, '<td valign="top">I love everything about it - the concept, the image, but the text at the top overwhelms the overall poster. Still a 7 from me.</td>', 'I love everything about it - the concept, the image, but the text at the top overwhelms the overall poster. Still a 7 from me.', '2010-05-07 04:51:18.000000', NULL, 1),
